<?php// teams/models/TeamMember.phpclass TeamMember {    private PDO $pdo;    public function __construct(PDO $pdo) {        $this->pdo = $pdo;    }    public function add(int $teamId, int $studentId, string $role = 'member'): void {        $team = (new Team($this->pdo))->findById($teamId);        if (!$team) {            throw new Exception("Team not found");        }        // Only leader can add members        if (!$this->isLeader($teamId, $_SESSION['user_id'])) {            throw new Exception("Only the team leader can add members");        }        // 1. Max 5 members        if ($this->getMemberCount($teamId) >= 5) {            throw new Exception("Team is already full (max 5 members)");        }        // 2. Only one leader        if ($role === 'leader') {            if ($this->hasLeader($teamId)) {                throw new Exception("Team already has a leader");            }        }        // 3. Student must be in same course/year and enrolled in unit        $stmt = $this->pdo->prepare("            SELECT s.course_id, s.year             FROM students s            JOIN enrollments e ON s.id = e.student_id            WHERE s.id = ? AND e.unit_id = ?        ");        $stmt->execute([$studentId, $team['unit_id']]);        $student = $stmt->fetch(PDO::FETCH_ASSOC);        if (!$student || $student['course_id'] != $team['course_id'] || $student['year'] != $team['year']) {            throw new Exception("Student is not eligible (different course/year or not enrolled)");        }        // 4. Student not already in any team for this assessment        $stmt = $this->pdo->prepare("            SELECT COUNT(*)             FROM team_members tm            JOIN teams t ON tm.team_id = t.id            WHERE tm.student_id = ? AND t.assessment_id = ?        ");        $stmt->execute([$studentId, $team['assessment_id']]);        if ($stmt->fetchColumn() > 0) {            throw new Exception("Student is already in another team for this assignment");        }        // 5. Not already in this team        $stmt = $this->pdo->prepare("            SELECT COUNT(*) FROM team_members             WHERE team_id = ? AND student_id = ?        ");        $stmt->execute([$teamId, $studentId]);        if ($stmt->fetchColumn() > 0) {            throw new Exception("Student is already a member of this team");        }        // Insert        $stmt = $this->pdo->prepare("            INSERT INTO team_members (team_id, student_id, role)            VALUES (?, ?, ?)        ");        $stmt->execute([$teamId, $studentId, $role]);    }    public function remove(int $teamId, int $studentId): void {        $team = (new Team($this->pdo))->findById($teamId);        if (!$team) throw new Exception("Team not found");        if (!$this->isLeader($teamId, $_SESSION['user_id'])) {            throw new Exception("Only the team leader can remove members");        }        // Leader cannot remove themselves if others are present        if ($studentId === $team['created_by'] && $this->getMemberCount($teamId) > 1) {            throw new Exception("Leader cannot leave while other members are present");        }        $stmt = $this->pdo->prepare("            DELETE FROM team_members             WHERE team_id = ? AND student_id = ?        ");        $stmt->execute([$teamId, $studentId]);    }    public function getMembers(int $teamId): array {        $stmt = $this->pdo->prepare("            SELECT tm.*, s.name, s.reg_number, s.email            FROM team_members tm            JOIN students s ON tm.student_id = s.id            WHERE tm.team_id = ?            ORDER BY tm.role DESC, s.name        ");        $stmt->execute([$teamId]);        return $stmt->fetchAll(PDO::FETCH_ASSOC);    }    public function getMemberCount(int $teamId): int {        $stmt = $this->pdo->prepare("SELECT COUNT(*) FROM team_members WHERE team_id = ?");        $stmt->execute([$teamId]);        return (int) $stmt->fetchColumn();    }    private function isLeader(int $teamId, int $studentId): bool {        $stmt = $this->pdo->prepare("            SELECT role FROM team_members             WHERE team_id = ? AND student_id = ?        ");        $stmt->execute([$teamId, $studentId]);        return $stmt->fetchColumn() === 'leader';    }    private function hasLeader(int $teamId): bool {        $stmt = $this->pdo->prepare("            SELECT COUNT(*) FROM team_members             WHERE team_id = ? AND role = 'leader'        ");        $stmt->execute([$teamId]);        return $stmt->fetchColumn() > 0;    }}